def clamp(value, lower, upper):
    if lower > upper:
        raise ValueError("lower exceeds upper")
    return max(min(value, upper), lower)

def strip_prefix(text, prefix):
    if not prefix:
        return text
    if text.startswith(prefix):
        return text[len(prefix):]
    return text

def rotate_left(items, steps):
    if not items:
        return []
    n = len(items)
    effective_steps = steps % n
    return items[effective_steps:] + items[:effective_steps]

class Counter:
    def __init__(self):
        self.value = 0
    def increment(self, step=1):
        # Ensure step is a strict positive integer (bool is invalid)
        if not isinstance(step, int) or isinstance(step, bool) or step <= 0:
            raise ValueError("step must be a strict positive integer")
        self.value += step
        return self.value

def triangular(n):
    if not isinstance(n, int) or isinstance(n, bool):
        raise ValueError("n must be a nonnegative integer excluding bool")
    if n < 0:
        raise ValueError("n must be nonnegative")
    return n * (n + 1) // 2

def gcd(a, b):
    a = abs(a)
    b = abs(b)
    while b:
        a, b = b, a % b
    return a

def rot13(text):
    result = ""
    for char in text:
        if 'a' <= char <= 'z':
            # Rotate lowercase letter
            rotated = ord('a') + (ord(char) - ord('a') + 13) % 26
            result += chr(rotated)
        elif 'A' <= char <= 'Z':
            # Rotate uppercase letter
            rotated = ord('A') + (ord(char) - ord('A') + 13) % 26
            result += chr(rotated)
        else:
            # Preserve non-ASCII letters, digits, punctuation, whitespace
            result += char
    return result

def mask_digits(text, mask):
    if not isinstance(mask, str) or len(mask) != 1:
        raise ValueError("mask must be a string of exactly one character")
    return ''.join(mask if c.isdigit() and ord(c) < 128 else c for c in text)

def prefix_products(values):
    if not values:
        return []
    result = []
    product = 1
    for num in values:
        product *= num
        result.append(product)
    return result

def transpose(rows):
    if not rows:
        return []
    # Check if all rows have the same length
    row_length = len(rows[0])
    for row in rows:
        if len(row) != row_length:
            raise ValueError("Rows must have the same length")
    # Transpose the matrix
    transposed = []
    for i in range(row_length):
        new_row = []
        for row in rows:
            new_row.append(row[i])
        transposed.append(new_row)
    return transposed

def register_name(state, name):
    if not isinstance(name, str):
        raise ValueError("name must be a string")
    normalized_name = name.strip()
    if not normalized_name:
        raise ValueError("name cannot be empty or whitespace only")
    if 'names' not in state:
        state = dict(state)
        state['names'] = []
    else:
        state = dict(state)
    if normalized_name in state['names']:
        raise ValueError(f"name '{normalized_name}' already registered")
    state['names'].append(normalized_name)
    return state
